					unm, err := caddyfile.UnmarshalModule(d, moduleID)
					if err != nil {
						return err
					}
					filter, ok := unm.(LogFieldFilter)
					if !ok {
						return d.Errf("module %s (%T) is not a logging.LogFieldFilter", moduleID, unm)
					}
