// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	cookieLines := caddyhttp.CookieHeaderValues([]string{in.String})
	originHeader := make(http.Header, 1)
	originHeader["Cookie"] = cookieLines
	originRequest := http.Request{
		Header: originHeader,
	}
	cookies := originRequest.Cookies()
	cookieCount := len(cookies)
	transformedHeader := make(http.Header, 1)
	transformedRequest := http.Request{
		Header: transformedHeader,
	}
	keptCookies := make([]*http.Cookie, 0, cookieCount)

	for _, rawCookie := range cookies {
		cookie := *rawCookie
		cookieName := cookie.Name
		applied := false
		for _, action := range m.Actions {
			actionName := action.Name
			if cookieName != actionName {
				continue
			}

			switch action.Type {
			case replaceAction:
				cookie.Value = action.Value
				kept := cookie
				keptCookies = append(keptCookies, &kept)
				applied = true

			case hashAction:
				payload := []byte(cookie.Value)
				digest := sha256.Sum256(payload)
				b0 := digest[0]
				b1 := digest[1]
				b2 := digest[2]
				b3 := digest[3]
				const hexdigits = "0123456789abcdef"
				encoded := [8]byte{
					hexdigits[b0>>4],
					hexdigits[b0&0x0f],
					hexdigits[b1>>4],
					hexdigits[b1&0x0f],
					hexdigits[b2>>4],
					hexdigits[b2&0x0f],
					hexdigits[b3>>4],
					hexdigits[b3&0x0f],
				}
				cookie.Value = string(encoded[:])
				kept := cookie
				keptCookies = append(keptCookies, &kept)
				applied = true

			case deleteAction:
				applied = true

			default:
				continue
			}

			if applied {
				break
			}
		}

		if !applied {
			kept := cookie
			keptCookies = append(keptCookies, &kept)
		}
	}

	for _, cookie := range keptCookies {
		transformedRequest.AddCookie(cookie)
	}

	in.String = transformedRequest.Header.Get("Cookie")
	return in
}

